import{_ as i,l,o as e,c as s,v as o,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"随机化算法直觉","description":"","frontmatter":{"title":"随机化算法直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/randomized-algo.md","filePath":"cs/randomized-algo.md","lastUpdated":1789023840000}'),c={name:"cs/randomized-algo.md"};function E(m,a,_,A,C,B){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="随机化算法直觉" tabindex="-1">随机化算法直觉 <a class="header-anchor" href="#随机化算法直觉" aria-label="Permalink to &quot;随机化算法直觉&quot;">​</a></h1><div class="epigraph"><p>硬币可以写进算法：Las Vegas 永远对、时间是随机变量；Monte Carlo 限时、以小概率错。</p><footer>—— 据 CLRS 第 5、7、34 章；Motwani and Raghavan, Randomized Algorithms, 1995 整理</footer></div><p>上一课<a href="/cs/approximation-ratio">近似比</a>的 \\(\\rho\\) 是确定性最坏倍数。<a href="/cs/quicksort-expected">快排与期望</a>已经用过算法内的硬币。本课不重做指示器求和。缺口是把随机化收成算法课的出口：两类错误、指纹与抽样、以及「期望多项式 / 高概率」与 NP 证书的关系。下一课起对象换成源程序字符串，不再抛硬币解图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定性最坏可能平方或指数，随机打乱或随机轴把对手的输入洗成期望好。Las Vegas：输出总正确，如随机快排、随机选择；分析 \\(E[T]\\)。Monte Carlo：可能错，如指纹判相等（多项式哈希碰撞）、随机化 Miller–Rabin 一类数论测试——本课点名素性，不写数论证明。缺口是分类，不是再证快排。</p><p>近似也可以随机：期望比或高概率比。与上一课确定性 \\(\\rho\\) 并列，不要混成「差不多」。RP、BPP 是复杂度类名字，本课点到：多项式时间 Monte Carlo 一边错；不把 \\(P\\stackrel{?}{=}BPP\\) 当定理。</p><h3 id="期望不是平均输入" tabindex="-1">期望不是平均输入 <a class="header-anchor" href="#期望不是平均输入" aria-label="Permalink to &quot;期望不是平均输入&quot;">​</a></h3><p>上一课快排已强调：硬币在算法里，输入可以任意固定。本课沿用。平均情形分析（输入分布）是另一模型，不在主干。</p><p><span class="marginnote">Motwani–Raghavan 教材是随机算法标准书。CLRS 用指示器、随机增量、指纹。Karger 最小割等点名不展开。指纹与<a href="/cs/hash-function">散列</a>同一碰撞语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清：错在哪一侧（否实例被当成是，或反之）、重复独立试验如何把错误指数压下去。期望线性选择、随机快排作 Las Vegas 例；指纹作 Monte Carlo 例。推导用线性期望，不必浓度不等式全文。</p>',11)),(e(),n(p,null,{default:r(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COIN%5B%22%E7%AE%97%E6%B3%95%E5%86%85%E7%A1%AC%E5%B8%81%22%5D%20--%3E%20LV%5B%22Las%20Vegas%EF%BC%9A%E6%80%BB%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20COIN%20--%3E%20MC%5B%22Monte%20Carlo%EF%BC%9A%E5%8F%AF%E9%94%99%22%5D%0A%20%20LV%20--%3E%20QT%5B%22%E9%9A%8F%E6%9C%BA%E5%BF%AB%E6%8E%92%20%2F%20%E9%80%89%E6%8B%A9%22%5D%0A%20%20MC%20--%3E%20FP%5B%22%E6%8C%87%E7%BA%B9%20%2F%20%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><a href="/cs/discrete-probability">离散概率</a>已有期望线性。本课只把算法类型接上去。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>去随机化（条件期望、有限独立）可以把部分硬币拿掉，本课不写完。NPC 搜索没有已知的随机多项式精确算法；随机化不自动把 3-SAT 放进 P。编译课的哈希词法、布局随机化（ASLR）是后课系统，不是本课的图算法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Chernoff 全文，不引入 PCP。不把密码学原语当随机算法习题。算法栏到此：图、串、范式、难解、近似与硬币都已开口。后课默认：随机化要声明 Las Vegas 还是 Monte Carlo。编译器通行证接源文本——字符串，不是随机图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Las Vegas 正确、时间随机；Monte Carlo 可错、可重复压错误。</li><li>硬币在算法内；不代替 NP 证书。</li><li>算法课收束；下一课编译管道从字符开始。</li><li>出处：CLRS 第 5、7 章；Motwani and Raghavan, 1995。</li></ul>',7))])}const P=i(c,[["render",E]]);export{u as __pageData,P as default};
